   259	): boolean {
   260		// Fail closed: a null/undefined scope set means the caller presented no
   261		// MCP scope claim. It must NOT be treated as full access.
   262		if (scopes == null) return false;
   263		if (scopes.length === 0) return false;
   264		// Session/anonymous bypass sentinel: scope dimension does not apply (these
   265		// callers are gated by role + public-readability upstream).
   266		if (scopes.includes("*")) return true;
   267		const scopeSet = new Set(scopes);
   268		if (requiredAccess === "read") {
   269			return (
   270				scopeSet.has("mcp:read") ||
   271				scopeSet.has("mcp:write") ||
   272				scopeSet.has("mcp:admin")
   273			);
   274		}
   275		if (requiredAccess === "write") {
   276			return scopeSet.has("mcp:write") || scopeSet.has("mcp:admin");
   277		}
