   172	/**
   173	 * Admin-tier auth gate.
   174	 *
   175	 * Admin-tier routes (agent CRUD, connection mutations, anything called by
   176	 * `lobu apply`) accept either:
   177	 *   - a better-auth session (`authSource === 'session'`), or
   178	 *   - a PAT/OAuth bearer that carries the `mcp:admin` scope.
   179	 *
   180	 * Read-only routes (list, get) keep using `mcpAuth` alone — a `mcp:read` PAT
   181	 * is fine for those.
   182	 *
   183	 * Returns a Response when the request must be rejected; returns null when the
   184	 * caller should proceed.
   185	 */
   186	export function requireSessionOrAdminPat(c: any): Response | null {
   187		const authSource = c.get("authSource") as "session" | "pat" | "oauth" | null;
   188	
   189		if (authSource === "session") {
   190			return null;
   191		}
   192	
   193		if (authSource === "pat" || authSource === "oauth") {
   194			const authInfo = c.get("mcpAuthInfo");
   195			const scopes: string[] = Array.isArray(authInfo?.scopes)
   196				? authInfo.scopes
   197				: [];
   198			if (scopes.includes("mcp:admin")) {
   199				return null;
   200			}
   201			return c.json(
   202				{
   203					error: "forbidden",
   204					error_description:
   205						"This route requires a web session or a token with mcp:admin scope.",
   206				},
   207				403
   208			);
   209		}
   210	
   211		return c.json({ error: "Authentication required" }, 401);
   212	}
