   277	/**
   278	 * Reconcile the user-scoped auth profiles for `(userId, agentId)` against the
   279	 * list the web client just submitted in a `PATCH /config` body.
   280	 *
   281	 *   - entries in `desired` that carry a non-empty `credential` are upserted
   282	 *     first (the secret is written to the secret store, the ref to the profile
   283	 *     JSON) — done before any removal so a failed write can't leave the user
   284	 *     with fewer credentials than they started with.
   285	 *   - profiles in the store but absent from `desired` are then removed (with
   286	 *     their secrets), so deleting a provider row in the UI actually deletes it.
   287	 *   - entries with an empty/absent `credential` are unchanged rows the client
   288	 *     round-tripped — left as-is so the stored secret is preserved.
   289	 *
   290	 * Throws if the auth-profiles manager is unavailable; the caller surfaces that
   291	 * rather than reporting a save that was dropped.
   292	 */
   293	async function reconcileAgentAuthProfiles(
   294		agentId: string,
   295		userId: string,
   296		desired: AuthProfile[]
   297	): Promise<void> {
   298		const manager = getLobuCoreServices()?.getAuthProfilesManager?.();
   299		if (!manager) {
   300			throw new Error(
   301				"Auth profile store is not available — retry once startup completes"
   302			);
   303		}
   304		const store = manager.getUserAuthProfileStore();
   305		for (const profile of desired) {
   306			const credential =
   307				typeof profile.credential === "string" ? profile.credential.trim() : "";
   308			if (!credential) continue;
   309			const metadata = sanitizeClientProfileMetadata(profile.metadata);
   310			await manager.upsertProfile({
   311				userId,
   312				agentId,
   313				id: profile.id,
   314				provider: profile.provider,
   315				credential,
   316				authType: profile.authType,
   317				label: profile.label,
   318				model: profile.model,
   319				...(metadata ? { metadata } : {}),
   320				makePrimary: true,
   321			});
   322		}
   323		const desiredIds = new Set(
   324			desired.map((profile) => profile.id).filter(Boolean)
   325		);
   326		const current = await store.list(userId, agentId);
   327		for (const existing of current) {
   328			if (!desiredIds.has(existing.id)) {
   329				await store.remove(userId, agentId, {
   330					provider: existing.provider,
   331					profileId: existing.id,
   332				});
   333			}
   334		}
   335	}
